package com.sumaye.restaurant.service;
import com.sumaye.restaurant.dto.CustomerRequest; import com.sumaye.restaurant.exception.*; import com.sumaye.restaurant.model.*; import com.sumaye.restaurant.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime;
@Service @RequiredArgsConstructor public class CustomerService { private final CustomerRepository customers; private final BranchRepository branches;
 @Transactional public Customer create(Long branchId,CustomerRequest r){Branch b=branches.findById(branchId).orElseThrow(()->new ResourceNotFoundException("Tawi halikupatikana"));String phone=r.getPhoneNumber().startsWith("0")?"+255"+r.getPhoneNumber().substring(1):r.getPhoneNumber();if(customers.findByRestaurantIdAndPhoneNumber(b.getRestaurant().getId(),phone).isPresent())throw new ApiException("Mteja mwenye namba hii tayari yupo");Customer c=new Customer();c.setRestaurant(b.getRestaurant());c.setBranch(b);c.setFullName(r.getFullName().trim());c.setPhoneNumber(phone);c.setEmail(r.getEmail());c.setAddress(r.getAddress());c.setNotes(r.getNotes());return customers.save(c);}
 @Transactional(readOnly=true) public Page<Customer> search(Long branchId,String q,Pageable p){Branch b=branches.findById(branchId).orElseThrow(()->new ResourceNotFoundException("Tawi halikupatikana"));return customers.search(b.getRestaurant().getId(),q==null?"":q,p);}}
